code.java:
class Solution {
    public int reductionOperations(int[] nums){
        Arrays.sort(nums);
        int answer=0;
        for(int i=1;i<nums.length;i++)if(nums[i]!=nums[i-1])answer+=i;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun reductionOperations(nums:IntArray):Int{
        nums.sort();
        var answer=0;
        for(i in 1 until nums.size)if(nums[i]!=nums[i-1])answer+=i;
        return answer
    }
}

code.cpp:
class Solution {
    public: int reductionOperations(vector<int>& nums){
        sort(nums.begin(),nums.end());
        int answer=0;
        for(int i=1;i<(int)nums.size();++i)if(nums[i]!=nums[i-1])answer+=i;
        return answer;
    }
};
